let _id = 0;
function uid() { return ++_id; }

// ── 사운드 엔진 (base64 직접 디코드, fetch 없음) ──
let _actx = null;
let _sndBuffers = {};
let _bgmSource = null;
let _audioReady = false;

function _getCtx() {
  if (!_actx) {
    try { _actx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e) {}
  }
  if (_actx && _actx.state === 'suspended') { try { _actx.resume(); } catch(e) {} }
  return _actx;
}

function _b64ToArrayBuffer(b64) {
  const bin = atob(b64);
  const buf = new ArrayBuffer(bin.length);
  const view = new Uint8Array(buf);
  for (let i = 0; i < bin.length; i++) view[i] = bin.charCodeAt(i);
  return buf;
}

function _loadOne(key, dataUri) {
  return new Promise(resolve => {
    try {
      const ctx = _getCtx();
      if (!ctx) { resolve(); return; }
      const b64 = dataUri.split(',')[1];
      const ab = _b64ToArrayBuffer(b64);
      ctx.decodeAudioData(ab, buf => { _sndBuffers[key] = buf; resolve(); }, () => resolve());
    } catch(e) { resolve(); }
  });
}

function preloadAllSounds() {
  return Promise.all([
    _loadOne('laser',    SND_LASER),
    _loadOne('explodeS', SND_EXPLODE_S),
    _loadOne('explodeB', SND_EXPLODE_B),
    _loadOne('clear',    SND_CLEAR),
    _loadOne('gameover', SND_GAMEOVER),
    _loadOne('hit',      SND_HIT),
    _loadOne('powerup',  SND_POWERUP),
    _loadOne('bgm',      SND_BGM),
  ]).then(() => { _audioReady = true; });
}

function playSound(key, volume=0.5) {
  try {
    const ctx = _getCtx();
    if (!ctx) return;
    const buf = _sndBuffers[key];
    if (!buf) return;
    const src = ctx.createBufferSource();
    src.buffer = buf;
    const gain = ctx.createGain();
    gain.gain.value = volume;
    src.connect(gain);
    gain.connect(ctx.destination);
    src.start(0);
  } catch(e) {}
}

function playBGM() {
  try {
    const ctx = _getCtx();
    if (!ctx) return;
    if (_bgmSource) { try { _bgmSource.stop(); } catch(e) {} _bgmSource = null; }
    const buf = _sndBuffers['bgm'];
    if (!buf) return;
    _bgmSource = ctx.createBufferSource();
    _bgmSource.buffer = buf;
    _bgmSource.loop = true;
    const gain = ctx.createGain();
    gain.gain.value = 0.20;
    _bgmSource.connect(gain);
    gain.connect(ctx.destination);
    _bgmSource.start(0);
  } catch(e) {}
}

function stopBGM() {
  if (_bgmSource) { try { _bgmSource.stop(); } catch(e) {} _bgmSource = null; }
}

function playBtn() { playSound('powerup', 0.30); }
function rnd(a, b) { return a + Math.random() * (b - a); }
function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

