function randomItem(stage) {
  const pool = [
    "MISSILE_UP","MISSILE_UP","MISSILE_UP",
    "SUB_MISSILE","SUB_MISSILE",
    ...(stage>=2?["SHIELD","SHIELD"]:[]),
    ...(stage>=2?["NOVA_BOMB"]:[]),
    ...(stage>=4?["OVERDRIVE"]:[]),
    ...(stage>=5?["GHOST_MODE"]:[]),
  ];
  return pool[Math.floor(Math.random()*pool.length)];
}

// ─── FORMATIONS ───────────────────────────────────────────────────────────────
const FORMATIONS = {
  V_FORMATION: n => Array.from({length:n},(_,i)=>{ const p=i-Math.floor(n/2); return {dx:p*44,dy:Math.abs(p)*28}; }),
  PINCER:      n => Array.from({length:n},(_,i)=>{ const s=i%2===0?-1:1,r=Math.floor(i/2); return {dx:s*(60+r*30),dy:r*20}; }),
  SPIRAL:      n => Array.from({length:n},(_,i)=>{ const a=(i/n)*Math.PI*2; return {dx:Math.cos(a)*55,dy:Math.sin(a)*28-30}; }),
  WAVE:        n => Array.from({length:n},(_,i)=>({dx:(i-Math.floor(n/2))*48,dy:Math.sin(i*1.1)*30})),
  AMBUSH:      n => Array.from({length:n},(_,i)=>{ const s=i%2===0?-1:1,r=Math.floor(i/2); return {dx:s*(GW*0.5+r*10),dy:r*50,ambush:true}; }),
};

const DRONE_TYPES = [
  {color:"#e05c2a",glowColor:"#ff7744",size:28,hp:1,score:10,shootChance:0.0008,shape:"scout"},
  {color:"#cc3366",glowColor:"#ff44aa",size:38,hp:2,score:25,shootChance:0.0015,shape:"assault"},
  {color:"#9933cc",glowColor:"#cc66ff",size:48,hp:3,score:50,shootChance:0.003, shape:"heavy"},
];

function makeFormation(stage, allowedForms) {
  const formName = allowedForms[Math.floor(Math.random()*allowedForms.length)];
  const typeIdx = Math.min(Math.floor(stage/2),2);
  const type = DRONE_TYPES[typeIdx];
  const count = formName==="SPIRAL"?6:formName==="AMBUSH"?4:(rnd(3,6)|0);
  const offsets = FORMATIONS[formName](count);
  const leadX = rnd(80,GW-80);
  const speed = 1.3+stage*0.15+Math.random()*0.4;
  return offsets.map(off=>({
    id:uid(), formName,
    x:off.ambush?(off.dx>0?GW+20:-20):clamp(leadX+off.dx,type.size,GW-type.size),
    y:off.ambush?rnd(80,250):-type.size*1.5-(off.dy||0),
    w:type.size,h:type.size,
    color:type.color,glowColor:type.glowColor,shape:type.shape,
    hp:type.hp,maxHp:type.hp,score:type.score,speed,
    wobble:Math.random()*Math.PI*2,wobbleSpeed:rnd(0.018,0.04),
    shootChance:type.shootChance*(1+stage*0.08),
    isAmbush:!!off.ambush,ambushDir:off.dx>0?-1:1,
    pincer:formName==="PINCER",pincerSide:(off.dx||0)>0?1:-1,
    stealth:false,splitOnDeath:false,
  }));
}

