// ─── PILOT RANK ───────────────────────────────────────────────────────────────
function calcRank(score, noDeathClear) {
  if(noDeathClear && score>=300000) return "S";
  if(noDeathClear || score>=250000) return "A";
  if(score>=150000) return "B";
  if(score>=80000)  return "C";
  return "D";
}
const RANK_COLORS = {S:"#ffee00",A:"#00eeff",B:"#00ff88",C:"#ff9900",D:"#ff4444"};

